if (!b.vehicle) {
  const ghast = Object.values(b.entities).find(e => e.name && e.name.toLowerCase().includes('ghast'));
  if (ghast) {
    await b.mount(ghast);
    await api.sleep(500);
  }
}
if (!b.vehicle) throw new Error('Not mounted on ghast');
if (api.args.yaw != null) await b.look(api.args.yaw, b.pitch, true);
b.setControlState('forward', fwd);
b.setControlState('jump', jump);
await api.sleep(dur);
b.clearControlStates();
return `Ghast steered (fwd=${fwd}, jump=${jump}) for ${dur}ms`;

