const bot = api.bot;
const ghast = Object.values(bot.entities).find(e => e.name && e.name.toLowerCase().includes('ghast'));
if (!ghast && !bot.vehicle) {
  throw new Error('No ghast found nearby or not mounted');
}
if (!bot.vehicle && ghast) {
  await bot.mount(ghast);
  await api.sleep(500);
}
if (bot.vehicle) {
  bot.setControlState('forward', true);
  bot.setControlState('jump', true);
  await api.sleep(2000);
  bot.setControlState('forward', false);
  bot.setControlState('jump', false);
  return 'Mounted and steered ghast successfully';
}
return 'Ready to steer ghast';
